using HvacErp.Domain.Enums;

namespace HvacErp.Application.Pdf;

/// <summary>
/// The built-in template for each <see cref="PdfDocumentType"/>: the original QuestPDF layout, with
/// its section headings in English (the product default) or Italian. This is both the seed content and the "Restore defaults" target.
/// Sections are generated by walking <see cref="PdfTemplateCatalog"/> so the two never drift; only
/// the default heading / body text and per-type header config live here.
/// </summary>
public static class PdfTemplateDefaults
{
    // No company footer lines by default: a deployment sets its contact / address lines in the
    // template editor (stored per template), so no installer's details are baked into the code.

    // QuestPDF Colors.Blue.Lighten4 — the current summary/total block background.
    private const string AccentBlue = "#BBDEFB";

    /// <summary>Display name of the seeded system template for a document type.</summary>
    public static string DefaultName(PdfDocumentType documentType) => documentType switch
    {
        PdfDocumentType.Quote => "Standard quote",
        PdfDocumentType.Repair => "Standard service sheet",
        PdfDocumentType.Installation => "Standard installation sheet",
        _ => "Standard",
    };

    /// <summary>
    /// The built-in layout for a document type (what <c>Restore defaults</c> writes), with section
    /// headings in <paramref name="language"/> (<see cref="PdfLabels.English"/> by default).
    /// </summary>
    public static PdfTemplateDefinition Default(PdfDocumentType documentType, string? language = PdfLabels.English)
    {
        var lang = PdfLabels.Supported.Contains(language ?? "") ? language! : PdfLabels.English;
        return new PdfTemplateDefinition
        {
            Page = new PdfPageConfig
            {
                Size = "A4",
                Margin = 30,
                FontFamily = "Calibri",
                BaseFontSize = 10,
                AccentColor = AccentBlue,
                Language = lang,
            },
            Header = Header(documentType),
            Sections = Sections(documentType, lang),
            Footer = new PdfFooterConfig
            {
                Lines = [],
                ShowPageNumbers = true,
            },
        };
    }

    private static PdfHeaderConfig Header(PdfDocumentType documentType) => documentType switch
    {
        PdfDocumentType.Quote => new PdfHeaderConfig
        {
            ShowLogo = true,
            ShowTitle = true,
            ShowDocumentMeta = true,
            ShowAgent = true,
            ShowClientBlock = true,
            ClientFields = ["fullName", "address", "phone", "mobile", "email"],
        },
        // Repair / installation headers never showed an agent line or the client e-mail.
        _ => new PdfHeaderConfig
        {
            ShowLogo = true,
            ShowTitle = true,
            ShowDocumentMeta = true,
            ShowAgent = false,
            ShowClientBlock = true,
            ClientFields = ["fullName", "address", "phone", "mobile"],
        },
    };

    private static List<PdfSection> Sections(PdfDocumentType documentType, string language)
    {
        var titles = language == PdfLabels.Italian ? ItalianText(documentType) : EnglishText(documentType);

        return PdfTemplateCatalog.For(documentType)
            // custom.text is the "add your own" section — never in the built-in template.
            .Where(entry => entry.Type != PdfTemplateCatalog.CustomText.Type)
            .Select(entry => new PdfSection
            {
                Type = entry.Type,
                Enabled = true,
                TitleOverride = titles.GetValueOrDefault(entry.Type)?.Title,
                Body = titles.GetValueOrDefault(entry.Type)?.Body,
                Columns = entry.Columns.Where(c => c.DefaultOn).Select(c => c.Key).ToList(),
                Options = entry.Options.ToDictionary(o => o.Key, o => o.DefaultOn),
            })
            .ToList();
    }

    private sealed record SectionText(string? Title, string? Body = null);

    private static Dictionary<string, SectionText> EnglishText(PdfDocumentType documentType) => documentType switch
    {
        PdfDocumentType.Quote => new()
        {
            ["quote.documentTitle"] = new(
                "QUOTE FOR THE SUPPLY AND INSTALLATION OF AN AIR-CONDITIONING SYSTEM",
                "DC inverter system for cooling, dehumidification, heating and air purification."),
            ["quote.installationSite"] = new("Installation site"),
            ["quote.externalUnits"] = new("OUTDOOR UNIT"),
            ["quote.internalUnits"] = new("INDOOR UNITS"),
            ["quote.ductedSystem"] = new("DUCTED SYSTEM"),
            ["quote.extras"] = new("INCLUDED OPTIONS"),
            ["quote.serviceItems"] = new("LABOUR AND MATERIALS"),
            ["quote.pricingSummary"] = new(null),
            ["quote.positionNotes"] = new(null),
            ["quote.floorPlan"] = new("FLOOR PLAN"),
        },
        PdfDocumentType.Repair => new()
        {
            ["repair.details"] = new(null),
            ["repair.interventionSite"] = new("Service site"),
            ["repair.description"] = new("WORK DESCRIPTION"),
            ["repair.appointments"] = new("APPOINTMENTS"),
            ["repair.serviceItems"] = new("LABOUR AND MATERIALS"),
            ["repair.floorPlan"] = new("FLOOR PLAN"),
            ["repair.total"] = new(null),
        },
        PdfDocumentType.Installation => new()
        {
            ["installation.site"] = new("Installation site"),
            ["installation.crew"] = new("ASSIGNED CREW"),
            ["installation.notes"] = new("NOTES"),
            ["installation.floorPlan"] = new("FLOOR PLAN"),
            ["installation.barcode"] = new("JOB ID"),
            ["installation.signatures"] = new(null),
        },
        _ => [],
    };

    private static Dictionary<string, SectionText> ItalianText(PdfDocumentType documentType) => documentType switch
    {
        PdfDocumentType.Quote => new()
        {
            ["quote.documentTitle"] = new(
                "PREVENTIVO FORNITURA POSA E IMPIANTO DI CLIMATIZZAZIONE",
                "Impianto con tecnologia DC INVERTER con funzione di raffrescamento, deumidificazione, riscaldamento e purificazione dell'aria."),
            ["quote.installationSite"] = new("Luogo di installazione"),
            ["quote.externalUnits"] = new("UNITÀ ESTERNA"),
            ["quote.internalUnits"] = new("UNITÀ INTERNA"),
            ["quote.ductedSystem"] = new("SISTEMA CANALIZZATO"),
            ["quote.extras"] = new("OPZIONI INCLUSE"),
            ["quote.serviceItems"] = new("LAVORAZIONI E MATERIALI"),
            ["quote.pricingSummary"] = new(null),
            ["quote.positionNotes"] = new(null),
            ["quote.floorPlan"] = new("PLANIMETRIA"),
        },
        PdfDocumentType.Repair => new()
        {
            ["repair.details"] = new(null),
            ["repair.interventionSite"] = new("Luogo intervento"),
            ["repair.description"] = new("DESCRIZIONE INTERVENTO"),
            ["repair.appointments"] = new("APPUNTAMENTI"),
            ["repair.serviceItems"] = new("LAVORAZIONI E MATERIALI"),
            ["repair.floorPlan"] = new("PLANIMETRIA"),
            ["repair.total"] = new(null),
